// PE Section Header Concept (Allocation)
struct IMAGE_SECTION_HEADER {
    char Name[8];          // e.g., .text, .data
    uint32_t VirtualSize;
    uint32_t RVA;          // Relative Virtual Address
    uint32_t SizeOfRawData;
    uint32_t PointerToRawData; // Disk offset
};

// Memory VA calculation at load time
#define ImageBase 0x400000 // Preferred Load Address
uint32_t CurrentVA = ImageBase + RVA;

// Characteristics (Memory Protection Flags)
#define MEM_EXECUTE 0x20000000
#define MEM_WRITE   0x80000000

// Relocation entry structure (.reloc section)
struct IMAGE_RELOC_ENTRY {
    uint16_t Offset : 12;    // Offset within the page
    uint16_t Type : 4;       // Fixup type (e.g., high/low word)
    // Relocation RVA = Page RVA + Offset
};

// If ImageBase != ActualLoadAddress:
// Fixup: *TargetVA += (ActualLoadAddress - ImageBase);


// Dynamic Linking (Import Address Table - IAT)
typedef void (*pfn_ExitProcess)(uint32_t);

// IAT slot (populated at runtime by loader)
pfn_ExitProcess IAT_ExitProcess;

// Linker places a jump instruction here:
void call_exit(uint32_t code) {
    IAT_ExitProcess(code);
    // Loader resolves IAT_ExitProcess to KERNEL32.dll VA
}
